CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE EXTENSION IF NOT EXISTS "pgcrypto";
CREATE EXTENSION IF NOT EXISTS "pg_trgm";

CREATE SEQUENCE IF NOT EXISTS public.listing_code_seq;
CREATE SEQUENCE IF NOT EXISTS public.operation_logs_id_seq;

CREATE OR REPLACE FUNCTION public.clean_arabic_text(input_text text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE STRICT
AS $function$
BEGIN
  IF input_text IS NULL OR input_text = '' THEN
    RETURN '';
  END IF;

  RETURN trim(
    regexp_replace(
      lower(
        translate(
          regexp_replace(
            regexp_replace(input_text, '[\u064B-\u065F\u0670]', '', 'g'), -- Tashkeel
            '\u0640', '', 'g'                                              -- Tatweel (ـ)
          ),
          'إأآٱىة',
          'ااايه'                                                         -- Alef, Yaa, Taa Marbouta
        )
      ),
      '\s+', ' ', 'g'
    )
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.fn_sync_listing_search_text()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_details JSONB := COALESCE(NEW.details, '{}'::jsonb);
  v_features_ar TEXT := '';
  v_features_en TEXT := '';
  v_search_ar TEXT;
  v_search_en TEXT;
BEGIN
  -- Extract features arrays into searchable text strings
  IF jsonb_typeof(v_details->'features') = 'array' THEN
    SELECT COALESCE(string_agg(value#>>'{}', ' '), '')
    INTO v_features_ar
    FROM jsonb_array_elements(v_details->'features');
  END IF;

  IF jsonb_typeof(v_details->'features_en') = 'array' THEN
    SELECT COALESCE(string_agg(value#>>'{}', ' '), '')
    INTO v_features_en
    FROM jsonb_array_elements(v_details->'features_en');
  END IF;

  -- 1. Arabic Search Corpus (Normalized via clean_arabic_text)
  v_search_ar := public.clean_arabic_text(
    COALESCE(NEW.title, '') || ' ' ||
    COALESCE(NEW.compound, '') || ' ' ||
    COALESCE(NEW.district, '') || ' ' ||
    COALESCE(NEW.location, '') || ' ' ||
    COALESCE(v_details->>'finishing', '') || ' ' ||
    COALESCE(v_details->>'orientation', '') || ' ' ||
    v_features_ar || ' ' ||
    CASE 
      WHEN NEW.property_type = 'studio' THEN 'استوديو استديو'
      WHEN NEW.bedrooms IS NOT NULL THEN (NEW.bedrooms::text || ' غرف ' || NEW.bedrooms::text || ' نوم')
      ELSE ''
    END
  );

  -- 2. English Search Corpus (Lowercased Latin tokens)
  v_search_en := lower(
    COALESCE(NEW.compound_en, '') || ' ' ||
    COALESCE(v_details->>'compound_en', '') || ' ' ||
    COALESCE(v_details->>'title_en', '') || ' ' ||
    COALESCE(v_details->>'finishing_en', '') || ' ' ||
    COALESCE(v_details->>'orientation_en', '') || ' ' ||
    v_features_en || ' ' ||
    CASE 
      WHEN NEW.property_type = 'studio' THEN 'studio'
      WHEN NEW.bedrooms IS NOT NULL THEN (NEW.bedrooms::text || ' bed ' || NEW.bedrooms::text || ' bedroom ' || NEW.bedrooms::text || ' beds')
      ELSE ''
    END
  );

  -- 3. Concatenate both corpora into search_text_normalized
  NEW.search_text_normalized := trim(v_search_ar || ' ' || v_search_en);
  
  -- 4. Sync elevated bathrooms column from details if not set directly
  IF NEW.bathrooms IS NULL AND (v_details->>'bathrooms') ~ '^[0-9]+$' THEN
    NEW.bathrooms := (v_details->>'bathrooms')::INTEGER;
  END IF;

  -- 5. Sync compound_en from details if top-level column is empty
  IF NEW.compound_en IS NULL AND v_details->>'compound_en' IS NOT NULL THEN
    NEW.compound_en := v_details->>'compound_en';
  END IF;

  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.listings_set_search_text()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.search_text_normalized := normalize_arabic(concat_ws(' ',
    NEW.location, NEW.compound, NEW.district, NEW.city,
    array_to_string(NEW.location_keywords, ' ')));
  RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.normalize_arabic(t text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
AS $function$
  SELECT btrim(
    regexp_replace(
      regexp_replace(
        translate(lower(coalesce(t, '')),
                  'أإآٱىةؤئ٠١٢٣٤٥٦٧٨٩ـ',
                  'اااايهوي0123456789'),
        '[\u064B-\u065F\u0670]', '', 'g'),
      '[[:space:].,،;:!?؟()"/|+*_=<>@#%^&~`]+', ' ', 'g'))
$function$;

CREATE OR REPLACE FUNCTION public.set_listing_image_agency_id()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.agency_id IS NULL THEN
    SELECT agency_id INTO NEW.agency_id FROM listings WHERE id = NEW.listing_id;
  END IF;
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.trg_fn_update_listings_search_text()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.search_text_normalized := normalize_arabic(
    COALESCE(NEW.title, '') || ' ' || 
    COALESCE(NEW.location, '') || ' ' || 
    COALESCE(NEW.compound, '') || ' ' || 
    COALESCE(NEW.district, '') || ' ' || 
    COALESCE(NEW.city, '') || ' ' ||
    COALESCE(array_to_string(NEW.location_keywords, ' '), '')
  );
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.update_listing_search_text()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.search_text_normalized := normalize_arabic(
    concat_ws(' ',
      NEW.code,
      NEW.title,
      NEW.property_type,
      NEW.listing_type,
      NEW.location,
      NEW.compound,
      NEW.district,
      NEW.city,
      array_to_string(NEW.location_keywords, ' '),
      NEW.details->>'clean_summary',
      NEW.details->>'short_summary'
    )
  );
  NEW.updated_at := NOW();
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.update_timestamp_column()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$function$;

CREATE TABLE IF NOT EXISTS public.agencies (
  id uuid DEFAULT gen_random_uuid() NOT NULL,
  name text NOT NULL,
  logo_url text,
  brand_color text DEFAULT '#0f172a'::text NOT NULL,
  accent_color text DEFAULT '#38bdf8'::text NOT NULL,
  created_at timestamp with time zone DEFAULT now() NOT NULL,
  primary_color character varying(7) DEFAULT '#0B132B'::character varying,
  secondary_color character varying(7) DEFAULT '#D4AF37'::character varying,
  flyer_theme text DEFAULT 'dark'::text NOT NULL,
  phone text,
  updated_at timestamp with time zone DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.brokers (
  id uuid DEFAULT gen_random_uuid() NOT NULL,
  agency_id uuid NOT NULL,
  phone_number text NOT NULL,
  name text NOT NULL,
  contact_phone text,
  role text DEFAULT 'broker'::text NOT NULL,
  is_active boolean DEFAULT true NOT NULL,
  created_at timestamp with time zone DEFAULT now() NOT NULL,
  last_active_at timestamp with time zone DEFAULT now(),
  preferred_lang character varying(10) DEFAULT 'ar'::character varying,
  phone_normalized text GENERATED ALWAYS AS (regexp_replace(phone_number, '[^0-9]'::text, ''::text, 'g'::text)) STORED
);

CREATE TABLE IF NOT EXISTS public.listings (
  id uuid DEFAULT gen_random_uuid() NOT NULL,
  code text NOT NULL,
  agency_id uuid NOT NULL,
  broker_id uuid,
  status text DEFAULT 'active'::text NOT NULL,
  title text,
  property_type text,
  listing_type text,
  price_value numeric,
  price_display text,
  area_value numeric,
  bedrooms integer,
  location text,
  features text[] DEFAULT '{}'::text[] NOT NULL,
  language text DEFAULT 'ar'::text NOT NULL,
  lat double precision,
  lng double precision,
  location_name text,
  raw_text text,
  details jsonb DEFAULT '{}'::jsonb NOT NULL,
  search_text text DEFAULT ''::text NOT NULL,
  flyer_url text,
  hero_position integer DEFAULT 0 NOT NULL,
  is_primary_developer boolean DEFAULT false NOT NULL,
  down_payment_value numeric,
  installment_years integer,
  installment_value numeric,
  payment_frequency text DEFAULT 'quarterly'::text,
  delivery_date text,
  maintenance_pct numeric DEFAULT 8,
  created_at timestamp with time zone DEFAULT now() NOT NULL,
  updated_at timestamp with time zone DEFAULT now() NOT NULL,
  compound text,
  district text,
  city text,
  location_keywords text[] DEFAULT '{}'::text[] NOT NULL,
  search_text_normalized text,
  flyer_wa_media_id text,
  flyer_wa_media_at timestamp with time zone,
  flyer_cache jsonb DEFAULT '{}'::jsonb,
  project_id uuid,
  inventory_type text DEFAULT 'resale_unit'::text NOT NULL,
  developer_unit_code text,
  payment_terms jsonb DEFAULT '{}'::jsonb NOT NULL,
  collateral jsonb DEFAULT '{}'::jsonb NOT NULL,
  bathrooms integer,
  compound_en character varying(120)
);

CREATE TABLE IF NOT EXISTS public.listing_images (
  id uuid DEFAULT gen_random_uuid() NOT NULL,
  listing_id uuid NOT NULL,
  agency_id uuid NOT NULL,
  position integer NOT NULL,
  url text NOT NULL,
  phash bit(64),
  role text
);

CREATE TABLE IF NOT EXISTS public.inbound_messages (
  msg_id text NOT NULL,
  phone_key text NOT NULL,
  payload jsonb NOT NULL,
  status text DEFAULT 'new'::text NOT NULL,
  attempts integer DEFAULT 0 NOT NULL,
  received_at timestamp with time zone DEFAULT now() NOT NULL,
  updated_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE IF NOT EXISTS public.processed_batches (
  batch_key text NOT NULL,
  agency_id uuid,
  listing_code text,
  created_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE IF NOT EXISTS public.broker_search_state (
  phone_key text NOT NULL,
  parsed jsonb NOT NULL,
  next_offset integer DEFAULT 0 NOT NULL,
  updated_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE IF NOT EXISTS public.operation_logs (
  id bigint DEFAULT nextval('operation_logs_id_seq'::regclass) NOT NULL,
  agency_id uuid,
  broker_id uuid,
  listing_code text,
  operation_type text NOT NULL,
  status text DEFAULT 'success'::text NOT NULL,
  error_code text,
  total_duration_ms integer DEFAULT 0,
  gemini_ms integer DEFAULT 0,
  media_download_ms integer DEFAULT 0,
  image_process_ms integer DEFAULT 0,
  flyer_render_ms integer DEFAULT 0,
  storage_upload_ms integer DEFAULT 0,
  db_ms integer DEFAULT 0,
  tokens_input integer DEFAULT 0,
  tokens_output integer DEFAULT 0,
  model_used text,
  estimated_cost_usd numeric(10,6) DEFAULT 0,
  created_at timestamp with time zone DEFAULT now() NOT NULL,
  metadata jsonb DEFAULT '{}'::jsonb
);

CREATE TABLE IF NOT EXISTS public.listing_drafts (
  broker_id uuid NOT NULL,
  agency_id uuid NOT NULL,
  broker_phone character varying(32) NOT NULL,
  media_ids text[] DEFAULT '{}'::text[],
  voice_ids text[] DEFAULT '{}'::text[],
  texts text[] DEFAULT '{}'::text[],
  custom_code character varying(64),
  updated_at timestamp with time zone DEFAULT now(),
  staged_data jsonb
);

CREATE TABLE IF NOT EXISTS public.projects (
  id uuid DEFAULT gen_random_uuid() NOT NULL,
  agency_id uuid NOT NULL,
  name text NOT NULL,
  developer_name text,
  district text,
  city text,
  delivery_year integer,
  maintenance_pct numeric DEFAULT 8.0,
  collateral jsonb DEFAULT '{}'::jsonb NOT NULL,
  media jsonb DEFAULT '{}'::jsonb NOT NULL,
  created_at timestamp with time zone DEFAULT now() NOT NULL,
  updated_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE IF NOT EXISTS public.broker_sessions (
  broker_id uuid NOT NULL,
  session_type character varying(64) NOT NULL,
  session_data jsonb DEFAULT '{}'::jsonb NOT NULL,
  expires_at timestamp with time zone NOT NULL
);

CREATE TABLE IF NOT EXISTS public.payment_plans (
  id uuid DEFAULT gen_random_uuid() NOT NULL,
  listing_id uuid,
  plan_id character varying(64) NOT NULL,
  name character varying(255) NOT NULL,
  years integer DEFAULT 0 NOT NULL,
  discount_pct numeric(5,2) DEFAULT 0.00,
  down_payment_pct numeric(5,2) DEFAULT 10.00,
  maintenance_pct numeric(5,2) DEFAULT 8.00,
  maintenance_splits integer DEFAULT 3,
  milestones jsonb DEFAULT '[]'::jsonb,
  created_at timestamp with time zone DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.processed_messages (
  message_id character varying(128) NOT NULL,
  sender_masked character varying(64) NOT NULL,
  direction character varying(16) DEFAULT 'inbound'::character varying NOT NULL,
  action_type character varying(64),
  created_at timestamp with time zone DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.audit_logs (
  id uuid DEFAULT gen_random_uuid() NOT NULL,
  agency_id uuid,
  broker_id uuid,
  action character varying(64) NOT NULL,
  severity character varying(16) DEFAULT 'info'::character varying,
  payload jsonb DEFAULT '{}'::jsonb,
  created_at timestamp with time zone DEFAULT now()
);

