CREATE TRIGGER trg_sync_listing_search_text BEFORE INSERT OR UPDATE ON public.listings FOR EACH ROW EXECUTE FUNCTION fn_sync_listing_search_text();
CREATE TRIGGER trg_update_listing_search_text BEFORE INSERT OR UPDATE ON public.listings FOR EACH ROW EXECUTE FUNCTION update_listing_search_text();
CREATE TRIGGER trg_update_listings_timestamp BEFORE UPDATE ON public.listings FOR EACH ROW EXECUTE FUNCTION update_timestamp_column();
